<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Pterodactyl\Models\Server; use Illuminate\Http\JsonResponse; use Pterodactyl\Facades\Activity; use Illuminate\Support\Facades\URL; use Pterodactyl\Models\Dezerx\DriveBackup; use Pterodactyl\Jobs\Dezerx\CopyBackupToDrive; use Pterodactyl\Services\Dezerx\Drive\GoogleDrive; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\DriveReadRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Addons\DriveWriteRequest; class DriveBackupController extends ClientApiController { public function index(DriveReadRequest $request, Server $server): JsonResponse { $link = DriveBackup::query()->where('server_id', $server->id)->first(); return new JsonResponse([ 'configured' => GoogleDrive::configured(), 'connected' => $link !== null, 'account' => $link?->account, 'intervalHours' => $link?->interval_hours ?? 0, 'keep' => $link?->keep ?? 5, 'lastRunAt' => $link?->last_run_at?->toIso8601String(), 'lastState' => $link?->last_state ?? 'idle', 'lastMessage' => $link?->last_message, 'connectUrl' => GoogleDrive::configured() ? URL::temporarySignedRoute('dezerx.drive.connect', now()->addMinutes(10), ['server' => $server->uuid]) : null, ]); } public function update(DriveWriteRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'intervalHours' => ['required', 'integer', 'between:0,168'], 'keep' => ['required', 'integer', 'between:1,50'], ]); $link = DriveBackup::query()->where('server_id', $server->id)->firstOrFail(); $link->forceFill([ 'interval_hours' => (int) $data['intervalHours'], 'keep' => (int) $data['keep'], ])->saveOrFail(); Activity::event('server:drive.settings') ->property(['intervalHours' => $link->interval_hours, 'keep' => $link->keep]) ->log(); return new JsonResponse(['intervalHours' => $link->interval_hours, 'keep' => $link->keep]); } public function run(DriveWriteRequest $request, Server $server): JsonResponse { $link = DriveBackup::query()->where('server_id', $server->id)->firstOrFail(); if ($link->last_state === 'running') { return new JsonResponse([ 'errors' => [['code' => 'AlreadyRunning', 'detail' => 'A copy to Drive is already running.']], ], 409); } $link->forceFill(['last_state' => 'running', 'last_message' => 'Queued.'])->saveOrFail(); CopyBackupToDrive::dispatch($link, true); Activity::event('server:drive.run')->log(); return new JsonResponse(['queued' => true, 'message' => 'Copying a backup to Drive. This takes a while.'], 202); } public function destroy(DriveWriteRequest $request, Server $server): JsonResponse { DriveBackup::query()->where('server_id', $server->id)->delete(); Activity::event('server:drive.disconnect')->log(); return new JsonResponse(['connected' => false]); } } 